+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collection;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Which customers a query should return.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ * <ul>
+ *   <li>every name term is a substring of the customer's first or last name;
+ *       matching ignores case and accents;</li>
+ *   <li>the customer has one of the statuses, or no statuses are given.</li>
+ * </ul>
+ *
+ * @param nameTerms normalized name terms; empty matches every name
+ * @param statuses  statuses to accept; empty accepts every status
+ */
+public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter(List.of(), Set.of());
+
+    public CustomerFilter {
+        nameTerms = List.copyOf(nameTerms);
+        statuses = Set.copyOf(statuses);
+    }
+
+    /**
+     * Builds a filter from what the user typed.
+     *
+     * @param name     text to split into whitespace-separated terms
+     * @param statuses statuses to accept; empty accepts every status
+     */
+    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
+        List<String> terms = Arrays.stream(normalize(name).split("[\\s\\p{Zs}]+"))
+                .filter(term -> !term.isEmpty())
+                .toList();
+        return new CustomerFilter(terms, Set.copyOf(statuses));
+    }
+
+    /** Whether the customer passes both parts of this filter. */
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return nameTerms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    /** Lower-cases the text and strips accents, so {@code Mäkinen} becomes {@code makinen}. */
+    private static String normalize(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT)
+                .strip();
+    }
+}
